using Saldo360.Api.Authentication; using Saldo360.Api.Errors; using Saldo360.Api.Observability; using Saldo360.Application.Goals; using Saldo360.Domain.Common; using Saldo360.Domain.Goals;
namespace Saldo360.Api.Goals;
public static class FinancialGoalAllocationEndpoints
{
 public static IEndpointRouteBuilder MapFinancialGoalAllocationEndpoints(this IEndpointRouteBuilder app){var g=app.MapGroup("/api/financial-workspaces/{workspaceId:guid}/financial-goals").RequireAuthorization();g.MapGet("/summary",Summary);g.MapGet("/{goalId:guid}/allocations",List);g.MapPost("/{goalId:guid}/contributions",Contribution).AddEndpointFilter<ValidateCsrfTokenFilter>();g.MapPost("/{goalId:guid}/withdrawals",Withdrawal).AddEndpointFilter<ValidateCsrfTokenFilter>();g.MapPost("/{goalId:guid}/allocations/{allocationId:guid}/cancel",Cancel).AddEndpointFilter<ValidateCsrfTokenFilter>();g.MapGet("/{goalId:guid}/progress",Progress);g.MapGet("/account-availability",Availability);return app;}
 private static async Task<IResult> List(Guid workspaceId,Guid goalId,CurrentUser u,FinancialGoalAllocationService s,CancellationToken ct)=>await u.GetUserIdAsync(ct) is not{ } uid?Results.Unauthorized():await s.ListAsync(workspaceId,goalId,uid,ct) is{ } x?Results.Ok(x.Select(Response.From)):Results.NotFound();
 private static Task<IResult> Contribution(Guid workspaceId,Guid goalId,AllocationRequest? x,CurrentUser u,FinancialGoalAllocationService s,FinancialOperationLogger operations,HttpContext context,CancellationToken ct)=>Create(workspaceId,goalId,FinancialGoalAllocationType.Contribution,x,u,s,operations,context,ct);
 private static Task<IResult> Withdrawal(Guid workspaceId,Guid goalId,AllocationRequest? x,CurrentUser u,FinancialGoalAllocationService s,FinancialOperationLogger operations,HttpContext context,CancellationToken ct)=>Create(workspaceId,goalId,FinancialGoalAllocationType.Withdrawal,x,u,s,operations,context,ct);
 private static async Task<IResult> Create(Guid f,Guid g,FinancialGoalAllocationType t,AllocationRequest? x,CurrentUser u,FinancialGoalAllocationService s,FinancialOperationLogger operations,HttpContext context,CancellationToken ct){if(await u.GetUserIdAsync(ct) is not{ } uid)return ApiProblems.Unauthorized();var started=operations.Start();var r=await s.CreateAsync(f,g,uid,t,new(x?.OperationId,x?.FinancialAccountId,x?.Amount,x?.EffectiveDate,x?.Description),ct);var code=r.Access switch{GoalAllocationAccess.Allowed=>"NONE",GoalAllocationAccess.Invalid=>"VALIDATION_ERROR",GoalAllocationAccess.Conflict=>ConflictCode(r.Message),_=>"RESOURCE_NOT_FOUND"};operations.Completed(context,started,t==FinancialGoalAllocationType.Contribution?"GoalContribution":"GoalWithdrawal",r.Access==GoalAllocationAccess.Allowed?"Succeeded":"Rejected",code);return Result(r,d=>Results.Created($"/api/financial-workspaces/{f}/financial-goals/{g}/allocations/{d.Id}",Response.From(d)));}
 private static async Task<IResult> Cancel(Guid workspaceId,Guid goalId,Guid allocationId,CurrentUser u,FinancialGoalAllocationService s,CancellationToken ct){if(await u.GetUserIdAsync(ct) is not{ } uid)return Results.Unauthorized();return Result(await s.CancelAsync(workspaceId,goalId,allocationId,uid,ct),d=>Results.Ok(Response.From(d!)));}
 private static async Task<IResult> Progress(Guid workspaceId,Guid goalId,CurrentUser u,FinancialGoalAllocationService s,CancellationToken ct)=>await u.GetUserIdAsync(ct) is not{ } uid?Results.Unauthorized():await s.ProgressAsync(workspaceId,goalId,uid,ct) is{ } x?Results.Ok(ProgressResponse.From(x)):Results.NotFound();
 private static async Task<IResult> Availability(Guid workspaceId,CurrentUser u,FinancialGoalAllocationService s,CancellationToken ct)=>await u.GetUserIdAsync(ct) is not{ } uid?Results.Unauthorized():await s.AvailabilityAsync(workspaceId,uid,ct) is{ } x?Results.Ok(x.Select(AvailabilityResponse.From)):Results.NotFound();
 private static async Task<IResult> Summary(Guid workspaceId,CurrentUser u,FinancialGoalAllocationService s,CancellationToken ct)=>await u.GetUserIdAsync(ct) is not{ } uid?Results.Unauthorized():await s.SummaryAsync(workspaceId,uid,ct) is{ } x?Results.Ok(SummaryResponse.From(x)):Results.NotFound();
 private static IResult Result(GoalAllocationResult r,Func<FinancialGoalAllocationDto,IResult> ok)=>r.Access switch{GoalAllocationAccess.NotFound=>ApiProblems.NotFound(),GoalAllocationAccess.Invalid=>ApiProblems.Validation(r.Errors!),GoalAllocationAccess.Conflict=>ApiProblems.Conflict(r.Message,ConflictCode(r.Message)),_=>ok(r.Allocation!)};
 private static string ConflictCode(string? message)=>message switch{"Saldo não alocado insuficiente."=>"INSUFFICIENT_FUNDS","OperationId já utilizado com conteúdo diferente."=>"DUPLICATE_OPERATION",_=>"OPERATION_CONFLICT"};
}
public sealed record AllocationRequest(Guid? OperationId,Guid? FinancialAccountId,string? Amount,DateOnly? EffectiveDate,string? Description);
public sealed record Response(Guid Id,Guid WorkspaceId,Guid GoalId,Guid FinancialAccountId,FinancialGoalAllocationType OperationType,string Amount,DateOnly EffectiveDate,Guid OperationId,string? Description,DateTimeOffset CreatedAt,DateTimeOffset? CancelledAt){public static Response From(FinancialGoalAllocationDto x)=>new(x.Id,x.WorkspaceId,x.GoalId,x.FinancialAccountId,x.OperationType,Money.Format(x.Amount),x.EffectiveDate,x.OperationId,x.Description,x.CreatedAt,x.CancelledAt);}
public sealed record ProgressResponse(Guid GoalId,string TargetAmount,string AllocatedAmount,string RemainingToTarget,string ProgressPercentage,bool IsFunded){public static ProgressResponse From(GoalProgressDto x)=>new(x.GoalId,Money.Format(x.TargetAmount),Money.Format(x.AllocatedAmount),Money.Format(x.RemainingToTarget),Money.Format(x.ProgressPercentage),x.IsFunded);}
public sealed record AvailabilityResponse(Guid FinancialAccountId,string RealizedBalance,string AllocatedAmount,string UnallocatedBalance){public static AvailabilityResponse From(GoalAccountAvailabilityDto x)=>new(x.FinancialAccountId,Money.Format(x.RealizedBalance),Money.Format(x.AllocatedAmount),Money.Format(x.UnallocatedBalance));}
public sealed record SummaryResponse(string AllocatedToGoals,string RealizedBalance,string UnallocatedRealizedBalance,int ActiveGoals,int CompletedGoals,int PausedGoals,bool CoverageComplete,IReadOnlyList<AvailabilityResponse> Accounts){public static SummaryResponse From(FinancialGoalSummaryDto x)=>new(Money.Format(x.AllocatedToGoals),Money.Format(x.RealizedBalance),Money.Format(x.UnallocatedRealizedBalance),x.ActiveGoals,x.CompletedGoals,x.PausedGoals,x.CoverageComplete,x.Accounts.Select(a=>new AvailabilityResponse(a.FinancialAccountId,Money.Format(a.RealizedBalance),Money.Format(a.AllocatedToGoals),Money.Format(a.UnallocatedRealizedBalance))).ToList());}
